-- Seed UI translation messages (module_code, program_code, message_code, message_en, message_local)
-- Auto-generated from i18n conversion pass across the Angular app.
ON CONFLICT (module_code, program_code, message_code) DO UPDATE SET
  message_en = EXCLUDED.message_en,
  message_local = EXCLUDED.message_local,
  updated_by = 'system',
  updated_date = NOW();
